1	import { CUSTOM_CURSOR } from "../config/component.config.js";
2	import type {
3	  CustomCursorOptions,
4	  CustomCursorState,
5	} from "../types/component.types.js";
6	import { FrameScheduler } from "../utils/FrameScheduler.js";
7	import { Component } from "../components/Component.js";
8	import { Aria } from "../utils/Aria.js";
9	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
10	
11	function isCursorOwnedElement(el: Element | null): boolean {
12	  if (!el || el instanceof Document) return false;
13	  return el.closest(`.${CUSTOM_CURSOR.block}`) !== null;
14	}
15	
16	function isInteractiveElement(el: Element | null): boolean {
17	  if (!el || el instanceof Document || isCursorOwnedElement(el)) return false;
18	  if (el.matches(CUSTOM_CURSOR.interactiveSelector)) return true;
19	  const cursor = window.getComputedStyle(el).cursor;
20	  return CUSTOM_CURSOR.interactiveCursorValues.includes(
21	    cursor as (typeof CUSTOM_CURSOR.interactiveCursorValues)[number],
22	  );
23	}
