25	export class CustomCursor extends Component {
26	  private static instance: CustomCursor | null = null;
27	
28	  private options: Required<CustomCursorOptions>;
29	  private rafId: number | null = null;
30	  private cleanup: Array<() => void> = [];
31	  private persistentCleanup: Array<() => void> = [];
32	  private cursorEl: HTMLDivElement | null = null;
33	  private reducedMotionQuery: MediaQueryList | null = null;
34	  private viewportHideQuery: MediaQueryList | null = null;
35	  private environmentBound = false;
36	  private x = 0;
37	  private y = 0;
38	  private targetX = 0;
39	  private targetY = 0;
40	  private pointerInsideViewport = false;
41	  private currentState: CustomCursorState = "idle";
42	  private appliedState: CustomCursorState = "idle";
43	
44	  constructor(options: CustomCursorOptions = {}) {
45	    super();
46	    this.options = {
47	      root: options.root ?? null,
48	      disableSelector: options.disableSelector ?? "",
49	    };
50	  }
51	
52	  static init(options: CustomCursorOptions = {}): void {
53	    if (!CUSTOM_CURSOR.enabled) {
54	      CustomCursor.dispose();
55	      return;
56	    }
57	
58	    if (!CustomCursor.instance) {
59	      CustomCursor.instance = new CustomCursor(options);
60	    } else {
61	      CustomCursor.instance.options = {
62	        ...CustomCursor.instance.options,
63	        ...options,
64	        root: options.root ?? CustomCursor.instance.options.root,
65	      };
66	    }
67	
68	    CustomCursor.instance.bindEnvironmentListeners();
69	    CustomCursor.instance.syncForCurrentPage();
70	  }
71	
72	  static dispose(): void {
73	    CustomCursor.instance?.dispose();
74	    CustomCursor.instance = null;
75	    CustomCursor.removeOrphanNodes();
76	  }
77	
78	  protected mount(): void {
79	    if (this.cursorEl) return;
80	
81	    CustomCursor.removeOrphanNodes();
82	
83	    this.cursorEl = document.createElement("div");
84	    this.cursorEl.id = "custom-cursor";
85	    this.cursorEl.className = `${CUSTOM_CURSOR.block} ${CUSTOM_CURSOR.modifierIdle}`;
86	    this.cursorEl.dataset.cursorState = "idle";
87	    Aria.setHidden(this.cursorEl, true);
88	
89	    document.body.appendChild(this.cursorEl);
90	    document.body.classList.add(CUSTOM_CURSOR.bodyClass);
91	
92	    this.x = 0;
93	    this.y = 0;
94	    this.targetX = 0;
95	    this.targetY = 0;
96	    this.pointerInsideViewport = false;
97	    this.currentState = "idle";
98	    this.appliedState = "idle";
99	
100	    this.reducedMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
101	    const onReducedMotionChange = (): void => this.syncReducedMotionClass();
102	    if (typeof this.reducedMotionQuery.addEventListener === "function") {
103	      this.reducedMotionQuery.addEventListener("change", onReducedMotionChange);
104	      this.cleanup.push(() =>
105	        this.reducedMotionQuery?.removeEventListener(
106	          "change",
107	          onReducedMotionChange,
108	        ),
109	      );
110	    } else if (typeof this.reducedMotionQuery.addListener === "function") {
111	      this.reducedMotionQuery.addListener(onReducedMotionChange);
112	      this.cleanup.push(() =>
113	        this.reducedMotionQuery?.removeListener(onReducedMotionChange),
114	      );
115	    }
116	    this.syncReducedMotionClass();
117	
118	    this.rafId = FrameScheduler.request(this.tick);
119	
120	    window.addEventListener("pointermove", this.onPointerMove, { passive: true });
121	    window.addEventListener("pointerleave", this.onPointerLeave);
122	    this.cleanup.push(() =>
123	      window.removeEventListener("pointermove", this.onPointerMove),
124	    );
125	    this.cleanup.push(() =>
126	      window.removeEventListener("pointerleave", this.onPointerLeave),
127	    );
128	  }
129	
130	  private unmount(): void {
131	    if (this.rafId !== null) {
132	      FrameScheduler.cancel(this.rafId);
133	      this.rafId = null;
134	    }
135	    this.cleanup.forEach((f) => f());
136	    this.cleanup = [];
137	    this.cursorEl?.remove();
138	    this.cursorEl = null;
139	    this.reducedMotionQuery = null;
140	    document.body.classList.remove(CUSTOM_CURSOR.bodyClass);
141	    CustomCursor.removeOrphanNodes();
142	  }
143	
144	  getVisibleState(): boolean {
145	    return this.cursorEl != null;
146	  }
147	
148	  protected applyVisibility(visible: boolean): void {
149	    if (visible) {
150	      this.mount();
151	      return;
152	    }
153	    this.unmount();
154	  }
155	
156	  override setVisibleOn(): void {
157	    this.mount();
158	  }
159	
160	  override setVisibleOff(): void {
161	    this.unmount();
162	  }
163	
164	  override dispose(): void {
165	    this.unmount();
166	    this.persistentCleanup.forEach((f) => f());
167	    this.persistentCleanup = [];
168	    this.viewportHideQuery = null;
169	    this.environmentBound = false;
170	    super.dispose();
171	  }
172	
173	  private bindEnvironmentListeners(): void {
174	    if (this.environmentBound || typeof window === "undefined") return;
175	    this.environmentBound = true;
176	
177	    const sync = (): void => this.syncForCurrentPage();
178	    window.addEventListener("resize", sync, { passive: true });
179	    this.persistentCleanup.push(() => window.removeEventListener("resize", sync));
180	
181	    if (typeof window.matchMedia !== "function") return;
182	    this.viewportHideQuery = window.matchMedia("(max-width: 768px)");
183	    if (typeof this.viewportHideQuery.addEventListener === "function") {
184	      this.viewportHideQuery.addEventListener("change", sync);
185	      this.persistentCleanup.push(() =>
186	        this.viewportHideQuery?.removeEventListener("change", sync),
187	      );
188	    } else if (typeof this.viewportHideQuery.addListener === "function") {
189	      this.viewportHideQuery.addListener(sync);
190	      this.persistentCleanup.push(() =>
191	        this.viewportHideQuery?.removeListener(sync),
192	      );
193	    }
194	  }
195	
196	  private syncForCurrentPage(): void {
197	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
198	    if (
199	      responsive.viewportWidth <= 768 ||
200	      !responsive.flags.hoverCapable ||
201	      responsive.flags.coarsePointer
202	    ) {
203	      this.unmount();
204	      return;
205	    }
206	
207	    const selector = this.options.disableSelector?.trim();
208	    const scope: ParentNode = this.options.root ?? document;
209	    if (selector && scope.querySelector(selector)) {
210	      this.unmount();
211	      return;
212	    }
213	
214	    this.mount();
215	  }
216	
217	  private tick = (): void => {
218	    this.rafId = FrameScheduler.request(this.tick);
219	    if (!this.cursorEl) return;
220	    const lerp = 0.52;
221	    this.x += (this.targetX - this.x) * lerp;
222	    this.y += (this.targetY - this.y) * lerp;
223	    this.cursorEl.style.left = `${this.x}px`;
224	    this.cursorEl.style.top = `${this.y}px`;
225	    if (this.appliedState !== this.currentState) this.applyState(this.currentState);
226	  };
227	
228	  private onPointerMove = (event: PointerEvent): void => {
229	    this.pointerInsideViewport = true;
230	    this.targetX = event.clientX;
231	    this.targetY = event.clientY;
232	    this.resolveCurrentState();
233	  };
234	
235	  private onPointerLeave = (): void => {
236	    this.pointerInsideViewport = false;
237	    this.currentState = "idle";
238	  };
239	
240	  private syncReducedMotionClass(): void {
241	    if (!this.cursorEl || !this.reducedMotionQuery) return;
242	    this.cursorEl.classList.toggle(
243	      CUSTOM_CURSOR.reducedMotionClass,
244	      this.reducedMotionQuery.matches,
245	    );
246	  }
247	
248	  private resolveCurrentState(): void {
249	    const under = this.pointerInsideViewport
250	      ? document.elementFromPoint(this.targetX, this.targetY)
251	      : null;
252	    this.currentState = isInteractiveElement(under) ? "interactive" : "idle";
253	  }
254	
255	  private applyState(state: CustomCursorState): void {
256	    this.appliedState = state;
257	    if (!this.cursorEl) return;
258	    this.cursorEl.dataset.cursorState = state;
259	    this.cursorEl.classList.toggle(CUSTOM_CURSOR.modifierIdle, state === "idle");
260	    this.cursorEl.classList.toggle(
261	      CUSTOM_CURSOR.modifierInteractive,
262	      state === "interactive",
263	    );
264	  }
265	
266	  private static removeOrphanNodes(): void {
267	    document
268	      .querySelectorAll<HTMLElement>(`#custom-cursor, .${CUSTOM_CURSOR.block}`)
269	      .forEach((el) => el.remove());
270	  }
271	}
