1	import { MARQUEE } from "../config/component.config.js";
2	import { Aria } from "../utils/Aria.js";
3	import type {
4	  GsapGlobal,
5	  WindowWithGsap,
6	} from "../types/gsap.types.js";
7	import type {
8	  MarqueeElements,
9	  MarqueeInitOptions,
10	  MarqueeItem,
11	} from "../types/component.types.js";
12	
13	function getGsap(): GsapGlobal | null {
14	  return (window as WindowWithGsap).gsap ?? null;
15	}
16	
17	function toNumber(value: string | undefined, fallback: number): number {
18	  const parsed = Number(value);
19	  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
20	  return parsed;
21	}
22	
23	function resolveElements(root: HTMLElement): MarqueeElements | null {
24	  const viewport = root.querySelector<HTMLElement>(MARQUEE.viewportSelector);
25	  const track = root.querySelector<HTMLElement>(MARQUEE.trackSelector);
26	  const item = root.querySelector<HTMLElement>(MARQUEE.itemSelector);
27	  if (!viewport || !track || !item) return null;
28	  return { root, viewport, track, item };
29	}
