11	export class ImagePreview extends Component {
12	  private readonly list: HTMLElement;
13	  private readonly preview: HTMLElement;
14	  private readonly previewImg: HTMLImageElement;
15	  private readonly itemSelector: string;
16	  private readonly imageDataAttr: string;
17	  private readonly offset: number;
18	  private readonly onMove: (event: MouseEvent) => void;
19	  private readonly bindings: ImagePreviewBinding[] = [];
20	  private hideTimer: number | null = null;
21	  private switchTimer: number | null = null;
22	  private currentItem: HTMLElement | null = null;
23	
24	  constructor(
25	    list: HTMLElement,
26	    preview: HTMLElement,
27	    previewImg: HTMLImageElement,
28	    itemSelector: string,
29	    imageDataAttr: string,
30	    offset: number,
31	  ) {
32	    super();
33	    this.list = list;
34	    this.preview = preview;
35	    this.previewImg = previewImg;
36	    this.itemSelector = itemSelector;
37	    this.imageDataAttr = imageDataAttr;
38	    this.offset = offset;
39	    this.onMove = Helpers.throttle((...args: unknown[]) => {
40	      const event = args[0];
41	      if (!(event instanceof MouseEvent)) return;
42	      this._move(event.clientX, event.clientY);
43	    }, IMAGE_PREVIEW.moveThrottleMs) as (event: MouseEvent) => void;
44	  }
45	
46	  static init(options: ImagePreviewOptions = {}): void {
47	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
48	    if (!responsive.flags.hoverCapable) {
49	      return;
50	    }
51	
52	    const listSelector = options.listSelector ?? IMAGE_PREVIEW.listSelector;
53	    const itemSelector = options.itemSelector ?? IMAGE_PREVIEW.itemSelector;
54	    const previewSelector =
55	      options.previewSelector ?? IMAGE_PREVIEW.previewSelector;
56	    const imageDataAttr =
57	      options.imageDataAttr ?? IMAGE_PREVIEW.imageDataAttr;
58	    const offset = options.offset ?? IMAGE_PREVIEW.offset;
59	
60	    const list = document.querySelector<HTMLElement>(listSelector);
61	    const preview = document.querySelector<HTMLElement>(previewSelector);
62	    const previewImg = preview?.querySelector<HTMLImageElement>("img");
63	    if (!list || !preview || !previewImg) return;
64	
65	    const imagePreview = new ImagePreview(
66	      list,
67	      preview,
68	      previewImg,
69	      itemSelector,
70	      imageDataAttr,
71	      offset,
72	    );
73	    imagePreview.init();
74	  }
75	
76	  protected mount(): void {
77	    const items = Array.from(
78	      this.list.querySelectorAll<HTMLElement>(this.itemSelector),
79	    );
80	    if (items.length === 0) return;
81	    items.forEach((item) => this._bindItem(item));
82	  }
83	
84	  protected applyVisibility(visible: boolean): void {
85	    this.preview.classList.toggle(IMAGE_PREVIEW.visibleClass, visible);
86	  }
87	
88	  getVisibleState(): boolean {
89	    return this.preview.classList.contains(IMAGE_PREVIEW.visibleClass);
90	  }
91	
92	  override dispose(): void {
93	    this._clearHideTimer();
94	    this._clearSwitchTimer();
95	    this.bindings.forEach((binding) => {
96	      binding.item.removeEventListener("mouseenter", binding.onEnter);
97	      binding.item.removeEventListener("mousemove", binding.onMove);
98	      binding.item.removeEventListener("mouseleave", binding.onLeave);
99	      delete binding.item.dataset[IMAGE_PREVIEW.boundFlag];
100	    });
101	    this.bindings.length = 0;
102	    super.dispose();
103	  }
104	
105	  private _bindItem(item: HTMLElement): void {
106	    if (item.dataset[IMAGE_PREVIEW.boundFlag] === "true") return;
107	    const binding: ImagePreviewBinding = {
108	      item,
109	      onEnter: (event) => this._onEnter(item, event),
110	      onMove: this.onMove,
111	      onLeave: () => this._scheduleHide(),
112	    };
113	    item.dataset[IMAGE_PREVIEW.boundFlag] = "true";
114	    item.addEventListener("mouseenter", binding.onEnter);
115	    item.addEventListener("mousemove", binding.onMove);
116	    item.addEventListener("mouseleave", binding.onLeave);
117	    this.bindings.push(binding);
118	  }
119	
120	  private _onEnter(item: HTMLElement, event: MouseEvent): void {
121	    this._clearHideTimer();
122	    this._clearSwitchTimer();
123	    this.preview.classList.remove(IMAGE_PREVIEW.closingClass);
124	
125	    const imageSrc = item.getAttribute(this.imageDataAttr);
126	    if (!imageSrc) return;
127	
128	    if (this._shouldSwitchImage(item)) {
129	      this._startClosing();
130	      this.switchTimer = window.setTimeout(() => {
131	        this.previewImg.src = imageSrc;
132	        this.preview.classList.remove(IMAGE_PREVIEW.closingClass);
133	        this._show();
134	        this.switchTimer = null;
135	      }, IMAGE_PREVIEW.switchDelayMs);
136	    } else {
137	      this.previewImg.src = imageSrc;
138	      this._show();
139	    }
140	
141	    this.currentItem = item;
142	    this._move(event.clientX, event.clientY);
143	  }
144	
145	  private _shouldSwitchImage(item: HTMLElement): boolean {
146	    return (
147	      this.preview.classList.contains(IMAGE_PREVIEW.visibleClass) &&
148	      this.currentItem !== null &&
149	      this.currentItem !== item
150	    );
151	  }
152	
153	  private _move(clientX: number, clientY: number): void {
154	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
155	    const width = this.preview.getBoundingClientRect().width || 320;
156	    const height = this.preview.getBoundingClientRect().height || 220;
157	    const left = this._resolveAxisPosition(
158	      clientX,
159	      width,
160	      responsive.viewportWidth,
161	    );
162	    const top = this._resolveAxisPosition(
163	      clientY,
164	      height,
165	      responsive.viewportHeight,
166	    );
167	    this._applyPreviewPosition({ x: left, y: top });
168	  }
169	
170	  private _resolveAxisPosition(
171	    clientPosition: number,
172	    boxSize: number,
173	    viewportSize: number,
174	  ): number {
175	    const offsetPosition = clientPosition + this.offset;
176	    const exceedsViewport = offsetPosition + boxSize > viewportSize - this.offset;
177	    const fallbackPosition = clientPosition - boxSize - this.offset;
178	    const nextPosition = exceedsViewport ? fallbackPosition : offsetPosition;
179	    return Math.max(this.offset, nextPosition);
180	  }
181	
182	  private _applyPreviewPosition(position: ElementTranslatePosition): void {
183	    this.preview.style.left = `${position.x}px`;
184	    this.preview.style.top = `${position.y}px`;
185	  }
186	
187	  private _scheduleHide(): void {
188	    this._clearHideTimer();
189	    this._clearSwitchTimer();
190	    this.hideTimer = window.setTimeout(() => {
191	      this._startClosing();
192	      window.setTimeout(() => {
193	        this.preview.classList.remove(IMAGE_PREVIEW.closingClass);
194	      }, IMAGE_PREVIEW.closeAnimationMs);
195	      this.currentItem = null;
196	      this.hideTimer = null;
197	    }, 80);
198	  }
199	
200	  private _startClosing(): void {
201	    this._hide();
202	    this.preview.classList.add(IMAGE_PREVIEW.closingClass);
203	  }
204	
205	  private _show(): void {
206	    this.setVisibleOn();
207	  }
208	
209	  private _hide(): void {
210	    this.setVisibleOff();
211	  }
212	
213	  private _clearHideTimer(): void {
214	    if (this.hideTimer === null) return;
215	    window.clearTimeout(this.hideTimer);
216	    this.hideTimer = null;
217	  }
218	
219	  private _clearSwitchTimer(): void {
220	    if (this.switchTimer === null) return;
221	    window.clearTimeout(this.switchTimer);
222	    this.switchTimer = null;
223	  }
224	}
