67	    hudPanel.bindEngine(engine);
68	    this._hudPanel = hudPanel;
69	  }
70	
71	  private _disposeTimelineComponents(): void {
72	    const resolver = TimelineRuntime.getInstance();
73	    for (const [key, instance] of this._timelineComponents) {
74	      resolver.unregisterTarget(key);
75	      instance.dispose();
76	    }
77	    this._timelineComponents.clear();
78	    this._hudPanel = null;
79	  }
