36	    if (this._disposed) return;
37	    if (this.element != null) {
38	      this.mount();
39	      return;
40	    }
41	    const el = document.querySelector<HTMLElement>(this.config.selector);
42	    if (!el) return;
43	    this.setElement(el);
44	    this.mount();
45	  }
46	
47	  setElement(el: HTMLElement | null): void {
48	    this.element = el;
49	  }
