56	  protected abstract applyVisibility(visible: boolean): void;
57	
58	  setVisibleOn(): void {
59	    this._setVisibility(true);
60	  }
61	
62	  setVisibleOff(): void {
63	    this._setVisibility(false);
64	  }
65	
66	  getVisibleState(): boolean {
67	    return this._visible;
68	  }
